func strErr(s string) error {
	if s == "" {
		return nil
	}
	return errors.New(s)
}

func mustJSON(v interface{}) string {
	b, _ := json.Marshal(v)
	return string(b)
}

// splitJSONStrings decodes a JSON string array.
func splitJSONStrings(s string) []string {
	var out []string
	if json.Unmarshal([]byte(s), &out) != nil {
		return nil
	}
	return out
}

// parseConnectionOwner / parseWIFIState / parseNetworkInterfaces decode the JSON
// the JNI shim returns for object-shaped callbacks.
func parseConnectionOwner(js string) (*ConnectionOwner, error) {
	var dto struct {
		UserId       int32    `json:"userId"`
		UserName     string   `json:"userName"`
		ProcessPath  string   `json:"processPath"`
		PackageNames []string `json:"packageNames"`
	}
	if err := json.Unmarshal([]byte(js), &dto); err != nil {
		return nil, err
	}
	c := &ConnectionOwner{UserId: dto.UserId, UserName: dto.UserName, ProcessPath: dto.ProcessPath}
	c.SetAndroidPackageNames(newIterator(dto.PackageNames))
	return c, nil
}

func parseWIFIState(js string) *WIFIState {
	var dto struct {
		SSID  string `json:"ssid"`
		BSSID string `json:"bssid"`
	}
	if json.Unmarshal([]byte(js), &dto) != nil {
		return nil
	}
	return NewWIFIState(dto.SSID, dto.BSSID)
}

func parseNetworkInterfaces(js string) NetworkInterfaceIterator {
	var dtos []struct {
		Index     int32    `json:"index"`
		MTU       int32    `json:"mtu"`
		Name      string   `json:"name"`
		Addresses []string `json:"addresses"`
		Flags     int32    `json:"flags"`
		Type      int32    `json:"type"`
		DNSServer []string `json:"dnsServer"`
		Gateway   []string `json:"gateway"`
		Metered   bool     `json:"metered"`
	}
	if json.Unmarshal([]byte(js), &dtos) != nil {
		return newIterator([]*NetworkInterface(nil))
	}
	out := make([]*NetworkInterface, 0, len(dtos))
	for _, d := range dtos {
		out = append(out, &NetworkInterface{
			Index: d.Index, MTU: d.MTU, Name: d.Name, Flags: d.Flags,
			Type: d.Type, Metered: d.Metered,
			Addresses: newIterator(d.Addresses),
			DNSServer: newIterator(d.DNSServer),
			Gateway:   newIterator(d.Gateway),
		})
	}
	return newIterator(out)
}

